package com.example.rokidkeyboardbridge;
import android.graphics.*;import android.view.View;import java.io.InputStream;
/** Lazy one-pose cache, fixed body, inner-face overlays and finite upper-body acknowledgements. */
final class ComfortPoseRenderer {
 private final View host;private int requested=-1,loaded=-1,generation;private long retryAfter;private Bitmap body;private Bitmap[] faces;private boolean loading;private int shownFace,priorFace;private long faceAt;
 private final Paint paint=new Paint(Paint.ANTI_ALIAS_FLAG|Paint.FILTER_BITMAP_FLAG);private final float[] mesh=new float[17*25*2],faceMesh=new float[13*13*2];
 ComfortPoseRenderer(View host){this.host=host;}
 boolean ready(int pose){return loaded==pose&&body!=null&&faces!=null;}
 void request(int pose){if(pose<0||pose>=ComfortPoseGeometry.ASSETS.length)return;if(loading){requested=pose;return;}if(ready(pose)||requested==pose&&android.os.SystemClock.uptimeMillis()<retryAfter)return;requested=pose;loading=true;final int token=++generation;
 new Thread(()->{Bitmap sheet=null,base=null;Bitmap[] patches=new Bitmap[4];try(InputStream in=host.getContext().getAssets().open(ComfortPoseGeometry.ASSETS[pose])){sheet=BitmapFactory.decodeStream(in);if(sheet==null||sheet.getWidth()!=ComfortPoseGeometry.width(pose)*2||sheet.getHeight()!=ComfortPoseGeometry.height(pose)*2)throw new IllegalStateException("Invalid comfort atlas");base=Bitmap.createBitmap(sheet,0,0,ComfortPoseGeometry.width(pose),ComfortPoseGeometry.height(pose));for(int v=0;v<4;v++){int[] f=ComfortPoseGeometry.crop(pose,v);Bitmap raw=Bitmap.createBitmap(sheet,f[0],f[1],f[2],f[3]);patches[v]=raw.copy(Bitmap.Config.ARGB_8888,true);patches[v].setHasAlpha(true);raw.recycle();Canvas mask=new Canvas(patches[v]);Paint p=new Paint(Paint.ANTI_ALIAS_FLAG);p.setShader(new ComposeShader(new LinearGradient(0,0,f[2],0,new int[]{Color.TRANSPARENT,Color.WHITE,Color.WHITE,Color.TRANSPARENT},new float[]{0,.12f,.88f,1},Shader.TileMode.CLAMP),new LinearGradient(0,0,0,f[3],new int[]{Color.TRANSPARENT,Color.WHITE,Color.WHITE,Color.TRANSPARENT},new float[]{0,.12f,.88f,1},Shader.TileMode.CLAMP),PorterDuff.Mode.MULTIPLY));if(pose>=4)p.setShader(new RadialGradient(f[2]*.5f,f[3]*.5f,Math.min(f[2],f[3])*.55f,new int[]{Color.WHITE,Color.WHITE,Color.TRANSPARENT},new float[]{0,.58f,1},Shader.TileMode.CLAMP));p.setXfermode(new PorterDuffXfermode(PorterDuff.Mode.DST_IN));mask.drawRect(0,0,f[2],f[3],p);}}
 catch(Exception|OutOfMemoryError error){if(base!=null)base.recycle();base=null;recycle(patches);patches=null;android.util.Log.w("LokiComfort","Comfort atlas decode failed",error);}finally{if(sheet!=null)sheet.recycle();}
 final Bitmap next=base;final Bitmap[] nextFaces=patches;host.post(()->{if(token!=generation){if(next!=null)next.recycle();recycle(nextFaces);return;}if(requested!=pose){loading=false;if(next!=null)next.recycle();recycle(nextFaces);request(requested);return;}if(body!=null)body.recycle();recycle(faces);body=next;faces=nextFaces;loaded=next==null?-1:pose;loading=false;retryAfter=next==null?android.os.SystemClock.uptimeMillis()+60000:0;shownFace=priorFace=0;faceAt=0;host.invalidate();});},"LokiComfortDecode").start();}
 boolean draw(Canvas c,int width,int height,int pose,int face,long age,long now,boolean speaking,int reaction,long reactionAge){request(pose);if(!ready(pose)||width<=0||height<=0)return false;int variant=ComfortPoseGeometry.expression(pose,face);if(shownFace!=variant||now<faceAt){priorFace=shownFace;shownFace=variant;faceAt=now;}float scale=ComfortPoseGeometry.scale(pose,width,height);int save=c.save();c.clipRect(0,0,width,height);c.translate((width-ComfortPoseGeometry.width(pose)*scale)*.5f,ComfortPoseGeometry.originY(pose,height,scale));c.scale(scale,scale);int k=0;for(int row=0;row<=24;row++)for(int col=0;col<=16;col++){mesh[k++]=ComfortPoseGeometry.width(pose)*(float)col/16;mesh[k++]=ComfortPoseGeometry.height(pose)*(float)row/24;}ComfortPoseGeometry.animate(mesh,16,24,pose,age,reaction,reactionAge,CharacterMotionTuning.scale()*CharacterMotionTuning.body());paint.setAlpha(255);c.drawBitmapMesh(body,16,24,mesh,0,null,0,paint);float t=Math.min(1,Math.max(0,now-faceAt)/260f);if(priorFace!=shownFace&&t<1)drawFace(c,pose,priorFace,1-t,now,speaking);drawFace(c,pose,shownFace,priorFace==shownFace?1:t,now,speaking);c.restoreToCount(save);return true;}
 private void drawFace(Canvas c,int pose,int variant,float alpha,long now,boolean speaking){if(alpha<=0||pose>=4&&variant==0&&!speaking&&Math.max(0,now)%4700>=280)return;int[] f=ComfortPoseGeometry.FACE[pose];long phase=Math.max(0,now)%4700;float blink=phase<280?1-Math.max(.12f,Math.abs(phase-140)/140f):0;int k=0;for(int row=0;row<=12;row++)for(int col=0;col<=12;col++){float u=col/12f,v=row/12f,dy=0;for(int eye=0;eye<2;eye++){float ex=eye==0?.35f:.69f,dx=(u-ex)/.17f,ey=(v-.36f)/.13f;dy-=(v-.36f)*blink*CharacterMotionTuning.eyes()*Math.max(0,1-dx*dx-ey*ey);}if(speaking){float dx=(u-.54f)/.22f,ey=(v-.78f)/.14f;dy+=(v-.78f)*.13f*(.5f+.5f*(float)Math.sin(now/100.0))*Math.max(0,1-dx*dx-ey*ey)*CharacterMotionTuning.face();}faceMesh[k++]=f[0]+u*f[2];faceMesh[k++]=f[1]+(v+dy)*f[3];}paint.setAlpha(Math.round(255*alpha));c.drawBitmapMesh(faces[variant],12,12,faceMesh,0,null,0,paint);}
 private static void recycle(Bitmap[] a){if(a!=null)for(Bitmap b:a)if(b!=null&&!b.isRecycled())b.recycle();}
 void release(){generation++;loading=false;requested=loaded=-1;if(body!=null)body.recycle();body=null;recycle(faces);faces=null;}
}
